      "app/src/main/java/com/rama/txori/managers/NotifyManager.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/managers/NotifyManager.kt b/app/src/main/java/com/rama/txori/managers/NotifyManager.kt\nnew file mode 100644\nindex 0000000..aa746b9\n--- /dev/null\n+++ b/app/src/main/java/com/rama/txori/managers/NotifyManager.kt\n@@ -0,0 +1,105 @@\n+package com.rama.txori.managers\n+\n+import android.content.Context\n+import android.hardware.camera2.CameraCharacteristics\n+import android.hardware.camera2.CameraManager\n+import android.os.Build\n+import android.os.Handler\n+import android.os.Looper\n+import android.os.VibrationEffect\n+import android.os.Vibrator\n+import android.os.VibratorManager\n+\n+/**\n+ * Single entry point for \"something finished\" feedback. Reads the user's\n+ * notification settings and fires only the effects they've enabled.\n+ */\n+object NotifyManager {\n+\n+    private val handler = Handler(Looper.getMainLooper())\n+\n+    /** Quiet tick, e.g. the last-few-seconds countdown beep. Respects the sounds toggle. */\n+    fun tick(context: Context) {\n+        if (prefs(context).getBoolean(PrefsManager.FileKeys.NOTIFICATION_SOUNDS, true)) {\n+            SoundManager.beepTick()\n+        }\n+    }\n+\n+    /**\n+     * Fire the \"finished\" notification according to the user's settings:\n+     * sound, vibration, screen flash, and/or camera flash.\n+     *\n+     * @param onFlashScreen invoked when the screen-flash setting is enabled;\n+     * the caller supplies how to actually flash its UI.\n+     */\n+    fun finish(context: Context, onFlashScreen: (() -> Unit)? = null) {\n+        val p = prefs(context)\n+\n+        if (p.getBoolean(PrefsManager.FileKeys.NOTIFICATION_SOUNDS, true)) {\n+            SoundManager.beepFinish()\n+        }\n+        if (p.getBoolean(PrefsManager.FileKeys.NOTIFICATION_VIBRATE, false)) {\n+            vibrate(context)\n+        }\n+        if (p.getBoolean(PrefsManager.FileKeys.NOTIFICATION_FLASH, false)) {\n+            onFlashScreen?.invoke()\n+        }\n+        if (p.getBoolean(PrefsManager.FileKeys.NOTIFICATION_FLASH_CAMERA, false)) {\n+            blinkTorch(context)\n+        }\n+    }\n+\n+    private fun prefs(context: Context) = PrefsManager.getInstance(context).prefs\n+\n+    private fun vibrate(context: Context) {\n+        val vibrator: Vibrator? = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {\n+            (context.getSystemService(Context.VIBRATOR_MANAGER_SERVICE) as? VibratorManager)\n+                ?.defaultVibrator\n+        } else {\n+            @Suppress(\"DEPRECATION\")\n+            context.getSystemService(Context.VIBRATOR_SERVICE) as? Vibrator\n+        }\n+        if (vibrator == null || !vibrator.hasVibrator()) return\n+\n+        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {\n+            vibrator.vibrate(VibrationEffect.createOneShot(400, VibrationEffect.DEFAULT_AMPLITUDE))\n+        } else {\n+            @Suppress(\"DEPRECATION\")\n+            vibrator.vibrate(400)\n+        }\n+    }\n+\n+    /** Blinks the rear camera torch a few times, e.g. for use-while-face-down/silent scenarios. */\n+    private fun blinkTorch(context: Context) {\n+        val cameraManager =\n+            context.getSystemService(Context.CAMERA_SERVICE) as? CameraManager ?: return\n+\n+        val cameraId = try {\n+            cameraManager.cameraIdList.firstOrNull { id ->\n+                cameraManager.getCameraCharacteristics(id)\n+                    .get(CameraCharacteristics.FLASH_INFO_AVAILABLE) == true\n+            }\n+        } catch (e: Exception) {\n+            null\n+        } ?: return\n+\n+        val blinkCount = 3\n+        val onMs = 150L\n+        val offMs = 150L\n+        var t = 0L\n+        repeat(blinkCount) {\n+            handler.postDelayed({ setTorch(cameraManager, cameraId, true) }, t)\n+            t += onMs\n+            handler.postDelayed({ setTorch(cameraManager, cameraId, false) }, t)\n+            t += offMs\n+        }\n+    }\n+\n+    private fun setTorch(cameraManager: CameraManager, cameraId: String, on: Boolean) {\n+        try {\n+            cameraManager.setTorchMode(cameraId, on)\n+        } catch (e: Exception) {\n+            // Torch may be unavailable (e.g. in use by another app); ignore.\n+        }\n+    }\n+}\n"
      },
      "app/src/main/java/com/rama/txori/managers/PrefsManager.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/managers/PrefsManager.kt b/app/src/main/java/com/rama/txori/managers/PrefsManager.kt\nindex 9673258..1f80462 100644\n--- a/app/src/main/java/com/rama/txori/managers/PrefsManager.kt\n+++ b/app/src/main/java/com/rama/txori/managers/PrefsManager.kt\n@@ -15,6 +15,10 @@ class PrefsManager private constructor(context: Context) : BohioPrefsManager(con\n         const val ROULETTE_TIMER = \"roulette:timer\"\n         const val ROULETTE_LIST = \"roulette:list\"\n         const val SESSION_COLLAPSED_IDS = \"session:collapsed_ids\"\n+        const val NOTIFICATION_VIBRATE = \"notification:vibrate\"\n+        const val NOTIFICATION_SOUNDS = \"notification:sounds\"\n+        const val NOTIFICATION_FLASH = \"notification:flash\"\n+        const val NOTIFICATION_FLASH_CAMERA = \"notification:flash_camera\"\n     }\n \n     // Local InitPrefs\n@@ -22,6 +26,10 @@ class PrefsManager private constructor(context: Context) : BohioPrefsManager(con\n         editor.putString(FileKeys.APP_TIMER, \"3000\")\n         editor.putString(FileKeys.ROULETTE_TIMER, \"3000\")\n         editor.putInt(FileKeys.ROULETTE_LIST, -1)\n+        editor.putBoolean(FileKeys.NOTIFICATION_SOUNDS, true)\n+        editor.putBoolean(FileKeys.NOTIFICATION_FLASH, false)\n+        editor.putBoolean(FileKeys.NOTIFICATION_FLASH_CAMERA, false)\n+        editor.putBoolean(FileKeys.NOTIFICATION_VIBRATE, false)\n     }\n \n     companion object {\n"
      },
