        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/widgets/WdRange.kt b/app/src/main/java/com/rama/txori/widgets/WdRange.kt\ndeleted file mode 100644\nindex 4e89733..0000000\n--- a/app/src/main/java/com/rama/txori/widgets/WdRange.kt\n+++ /dev/null\n@@ -1,121 +0,0 @@\n-package com.rama.txori.widgets\n-\n-import android.content.Context\n-import android.util.AttributeSet\n-import android.view.LayoutInflater\n-import android.widget.Button\n-import android.widget.LinearLayout\n-import androidx.core.content.withStyledAttributes\n-import com.rama.txori.R\n-\n-class WdRange @JvmOverloads constructor(\n-    context: Context,\n-    attrs: AttributeSet? = null,\n-    defStyleAttr: Int = 0\n-) : LinearLayout(context, attrs, defStyleAttr) {\n-\n-    private val container: LinearLayout\n-\n-    private val allButtons = mutableListOf<Button>()\n-\n-    private var selectedIndex = -1\n-\n-    var onValueChanged: ((String) -> Unit)? = null\n-\n-    init {\n-        orientation = VERTICAL\n-\n-        LayoutInflater.from(context).inflate(\n-            R.layout.wd_range,\n-            this,\n-            true\n-        )\n-\n-        container = findViewById(R.id.container)\n-\n-        attrs?.let {\n-            context.withStyledAttributes(it, R.styleable.WdRange) {\n-\n-                val values: List<String> = when {\n-                    hasValue(R.styleable.WdRange_valuesArray) -> {\n-                        val arrayRes = getResourceId(R.styleable.WdRange_valuesArray, 0)\n-                        if (arrayRes != 0) context.resources.getStringArray(arrayRes).toList()\n-                        else emptyList()\n-                    }\n-                    hasValue(R.styleable.WdRange_values) -> {\n-                        getString(R.styleable.WdRange_values)\n-                            ?.split(\",\")\n-                            ?.map { it.trim() }\n-                            ?.filter { it.isNotEmpty() }\n-                            ?: emptyList()\n-                    }\n-                    else -> emptyList()\n-                }\n-\n-                setValues(values)\n-            }\n-        }\n-    }\n-\n-    private fun setValues(values: List<String>) {\n-\n-        container.removeAllViews()\n-        allButtons.clear()\n-\n-        values.forEachIndexed { index, value ->\n-\n-            val button = Button(\n-                context,\n-                null,\n-                0,\n-                R.style.BTN_range\n-            ).apply {\n-\n-                text = value\n-\n-                layoutParams = LayoutParams(\n-                    0,\n-                    LayoutParams.WRAP_CONTENT,\n-                    1f\n-                )\n-\n-                setOnClickListener {\n-                    select(index)\n-                }\n-            }\n-\n-            allButtons.add(button)\n-            container.addView(button)\n-        }\n-\n-        if (values.isNotEmpty()) {\n-            select(0)\n-        }\n-    }\n-\n-    private fun select(index: Int) {\n-\n-        selectedIndex = index\n-\n-        allButtons.forEachIndexed { i, button ->\n-\n-            button.isSelected = i == index\n-\n-            // optional\n-            button.alpha =\n-                if (i == index) 1f\n-                else 0.5f\n-        }\n-\n-        onValueChanged?.invoke(\n-            allButtons[index].text.toString()\n-        )\n-    }\n-\n-    fun getValue(): String? {\n-        return allButtons\n-            .getOrNull(selectedIndex)\n-            ?.text\n-            ?.toString()\n-    }\n-}\n\\ No newline at end of file\n"
