      "app/src/main/java/com/rama/txori/CsActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/CsActivity.kt b/app/src/main/java/com/rama/txori/CsActivity.kt\nindex 0b9d167..5091593 100644\n--- a/app/src/main/java/com/rama/txori/CsActivity.kt\n+++ b/app/src/main/java/com/rama/txori/CsActivity.kt\n@@ -1,18 +1,32 @@\n package com.rama.txori\n \n import android.app.Activity\n+import android.content.Context\n import android.os.Build\n import android.os.Bundle\n import android.view.View\n import android.view.WindowInsets\n import android.view.WindowManager\n import com.rama.txori.managers.FontManager\n+import com.rama.txori.managers.ThemeManager\n import com.rama.txori.utils.dp\n+import com.rama.txori.managers.PrefsManager\n+import com.rama.txori.utils.LocaleHelper\n \n abstract class CsActivity : Activity() {\n \n+    val prefs by lazy { PrefsManager.getInstance(this) }\n+    private var lastKnownAppLanguage: String? = null\n+    private var lastKnownTheme: String? = null\n+\n+    override fun attachBaseContext(newBase: Context) {\n+        super.attachBaseContext(LocaleHelper.wrapContext(newBase))\n+    }\n+\n     override fun onCreate(savedInstanceState: Bundle?) {\n         super.onCreate(savedInstanceState)\n+        lastKnownAppLanguage = prefs.getAppLanguage()\n+        lastKnownTheme = prefs.getTheme()\n \n         // Allow drawing behind system bars\n         if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {\n@@ -32,12 +46,64 @@ abstract class CsActivity : Activity() {\n         }\n     }\n \n-    /**\n-     * Apply the custom font to the entire view tree rooted at [root].\n-     * Call this after setContentView() in every activity subclass.\n-     */\n-    protected fun applyFont(root: View) {\n-        FontManager.applyToView(this, root)\n+    override fun onResume() {\n+        super.onResume()\n+\n+        val currentLanguage = prefs.getAppLanguage()\n+        if (currentLanguage != lastKnownAppLanguage) {\n+            lastKnownAppLanguage = currentLanguage\n+            recreate()\n+            return\n+        }\n+\n+        val currentTheme = prefs.getTheme()\n+        if (currentTheme != lastKnownTheme) {\n+            lastKnownTheme = currentTheme\n+            recreate()\n+            return\n+        }\n+\n+        val root = findViewById<View>(android.R.id.content)\n+        ThemeManager.applyTheme(this, root)\n+    }\n+\n+    fun refreshFont() {\n+        val root = findViewById<View>(android.R.id.content)\n+        FontManager.applyFont(this, root)\n+    }\n+\n+    fun applyCurrentTheme(root: View? = null) {\n+        val target = root ?: findViewById<View>(android.R.id.content)\n+        ThemeManager.applyTheme(this, target)\n+        applyNavBarColor()\n+    }\n+\n+    private fun applyNavBarColor() {\n+        val palette = ThemeManager.paletteFor(prefs.getTheme(), this)\n+        window.navigationBarColor = palette.bg_1\n+        window.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(palette.bg_1))\n+    }\n+\n+    protected fun updateSystemBars(root: View) {\n+        if (prefs.isSystemBarVisible()) {\n+            window.decorView.systemUiVisibility =\n+                View.SYSTEM_UI_FLAG_LAYOUT_STABLE\n+        } else {\n+            window.decorView.systemUiVisibility =\n+                View.SYSTEM_UI_FLAG_FULLSCREEN or\n+                        View.SYSTEM_UI_FLAG_LAYOUT_STABLE or\n+                        View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN or\n+                        View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY\n+        }\n+        root.requestApplyInsets()\n+    }\n+\n+    override fun onWindowFocusChanged(hasFocus: Boolean) {\n+        super.onWindowFocusChanged(hasFocus)\n+        if (hasFocus) {\n+            val root = findViewById<View>(android.R.id.content)\n+            updateSystemBars(root)\n+        }\n     }\n \n     protected fun applyEdgeToEdgePadding(root: View) {\n@@ -80,4 +146,4 @@ abstract class CsActivity : Activity() {\n             insets\n         }\n     }\n-}\n+}\n\\ No newline at end of file\n"
      },
      "app/src/main/java/com/rama/txori/activities/AboutActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/activities/AboutActivity.kt b/app/src/main/java/com/rama/txori/activities/AboutActivity.kt\nnew file mode 100644\nindex 0000000..94e52b9\n--- /dev/null\n+++ b/app/src/main/java/com/rama/txori/activities/AboutActivity.kt\n@@ -0,0 +1,37 @@\n+package com.rama.txori.activities\n+\n+import android.content.Intent\n+import android.net.Uri\n+import android.os.Bundle\n+import android.view.View\n+import android.widget.TextView\n+import com.rama.txori.CsActivity\n+import com.rama.txori.R\n+\n+class AboutActivity : CsActivity() {\n+\n+    override fun onCreate(savedInstanceState: Bundle?) {\n+        super.onCreate(savedInstanceState)\n+\n+        setContentView(R.layout.view_about)\n+\n+        val root = findViewById<View>(android.R.id.content)\n+        applyEdgeToEdgePadding(root)\n+        applyCurrentTheme(root)\n+\n+        val closeButton = findViewById<View>(R.id.close_button)\n+        closeButton.setOnClickListener {\n+            finish()\n+        }\n+\n+        val discordButton = findViewById<View>(R.id.discord_button)\n+        discordButton.setOnClickListener {\n+            val intent = Intent(Intent.ACTION_VIEW, Uri.parse(\"https://discord.gg/zFFupY8PFE\"))\n+            startActivity(intent)\n+        }\n+\n+        val version = packageManager.getPackageInfo(packageName, 0).versionCode\n+        val nameView = findViewById<TextView>(R.id.name_version)\n+        nameView.text = getString(R.string.app_name) + ' ' + version\n+    }\n+}\n\\ No newline at end of file\n"
      },
