    "f847046a3702b3b26b28ae2ec086ed29d9905bdc": {
      "app/src/main/java/com/rama/txori/activities/MainActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/activities/MainActivity.kt b/app/src/main/java/com/rama/txori/activities/MainActivity.kt\nindex 92fb2ba..db0d52b 100644\n--- a/app/src/main/java/com/rama/txori/activities/MainActivity.kt\n+++ b/app/src/main/java/com/rama/txori/activities/MainActivity.kt\n@@ -285,7 +285,10 @@ class MainActivity : CsActivity() {\n         remainingMs = row.task.duration * 1_000L\n         adapter.setActiveItemIndex(index)\n         listView.post {\n-            listView.setSelectionFromTop(index, 0)\n+            val visiblePos = adapter.rawIndexToVisiblePosition(index)\n+            if (visiblePos >= 0) {\n+                listView.setSelectionFromTop(visiblePos, 0)\n+            }\n         }\n         updateNextTaskDisplay()\n         launchTimer(remainingMs)\n"
      },
      "app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt b/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt\nindex e20048e..2f8d76b 100644\n--- a/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt\n+++ b/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt\n@@ -67,7 +67,7 @@ class SessionAdapter(\n     }\n \n     // Maps a raw index in items[] to its visible ListView position, or -1 if hidden.\n-    private fun rawIndexToVisiblePosition(rawIndex: Int): Int {\n+    fun rawIndexToVisiblePosition(rawIndex: Int): Int {\n         val item = items.getOrNull(rawIndex) ?: return -1\n         // If it's a row in a collapsed session it isn't visible at all\n         if (item is SessionItem.Row && collapsedSessions.contains(item.sessionId)) return -1\n"
      }
    },
