      "app/src/main/java/com/rama/txori/activities/MainActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/activities/MainActivity.kt b/app/src/main/java/com/rama/txori/activities/MainActivity.kt\nindex 133687d..386e910 100644\n--- a/app/src/main/java/com/rama/txori/activities/MainActivity.kt\n+++ b/app/src/main/java/com/rama/txori/activities/MainActivity.kt\n@@ -5,6 +5,7 @@ import android.os.Bundle\n import android.os.CountDownTimer\n import android.view.View\n import android.widget.EditText\n+import android.widget.ImageView\n import android.widget.ListView\n import android.widget.TextView\n import com.rama.txori.CsActivity\n@@ -66,9 +67,10 @@ class MainActivity : CsActivity() {\n             findViewById<WdButton>(R.id.edit_button)\n         val repeatTaskButton = findViewById<View>(R.id.repeat_task)\n         val increaseTimeButton = findViewById<View>(R.id.increase_duration)\n-        val completeTaskButton = findViewById<View>(R.id.complete_task)\n+        val playTimeButton = findViewById<View>(R.id.start_task)\n         val skipTaskButton = findViewById<View>(R.id.skip_task)\n         val timeContainer = findViewById<View>(R.id.time_container)\n+        var globalPlayPauseicon = playTimeButton.findViewById<ImageView>(R.id.play_pause_icon)\n \n         db = dbHelper.writableDatabase\n         loadItems()\n@@ -104,9 +106,35 @@ class MainActivity : CsActivity() {\n             }\n         }\n \n-        val advance: (View) -> Unit = { advanceToNext() }\n-        completeTaskButton.setOnClickListener(advance)\n-        skipTaskButton.setOnClickListener(advance)\n+        playTimeButton.setOnClickListener {\n+            if (currentItemIndex < 0) return@setOnClickListener\n+\n+            if (isRunning) {\n+                // PAUSE\n+                pauseTimer()\n+                globalTimer?.cancel()\n+\n+                setPlayingState(false)\n+\n+            } else {\n+                // PLAY / RESUME\n+                setPlayingState(true)\n+\n+                if (remainingMs <= 0L) {\n+                    launchTimer(remainingMs)\n+                } else {\n+                    resumeTimer()\n+                }\n+\n+                if (globalRemainingMs > 0) {\n+                    launchGlobalTimer(globalRemainingMs)\n+                }\n+            }\n+        }\n+\n+        skipTaskButton.setOnClickListener({\n+            advanceToNext()\n+        })\n \n         val addGroupButton = findViewById<WdButton>(R.id.add_group_button)\n         addGroupButton.setOnClickListener {\n@@ -136,6 +164,21 @@ class MainActivity : CsActivity() {\n         }\n     }\n \n+    private fun setPlayingState(playing: Boolean) {\n+        isRunning = playing\n+\n+        adapter.setGroupPlayingState(activeSessionId, playing)\n+\n+        val icon = if (playing) {\n+            R.drawable.icon_pause\n+        } else {\n+            R.drawable.icon_play\n+        }\n+\n+        findViewById<ImageView>(R.id.play_pause_icon)\n+            ?.setImageResource(icon)\n+    }\n+\n     //  Data loading\n \n     private fun loadItems() {\n@@ -157,11 +200,11 @@ class MainActivity : CsActivity() {\n             activeSessionId == sessionId && isRunning -> {\n                 pauseTimer()\n                 globalTimer?.cancel()\n-                adapter.setGroupPlayingState(sessionId, false)\n+                setPlayingState(false)\n             }\n \n             activeSessionId == sessionId && !isRunning && currentItemIndex >= 0 -> {\n-                adapter.setGroupPlayingState(sessionId, true)\n+                setPlayingState(true)\n                 resumeTimer()\n                 launchGlobalTimer(globalRemainingMs)\n             }\n@@ -169,10 +212,14 @@ class MainActivity : CsActivity() {\n             else -> {\n                 stopCurrentTimer()\n                 globalTimer?.cancel()\n+                // Clear icon on the previously active session if different\n+                if (activeSessionId != -1L && activeSessionId != sessionId) {\n+                    adapter.setGroupPlayingState(activeSessionId, false)\n+                }\n                 activeSessionId = sessionId\n                 globalRemainingMs = calculateSessionRemainingMs(sessionId, startIndex)\n                 startFromIndex(startIndex)\n-                adapter.setGroupPlayingState(sessionId, true)\n+                setPlayingState(true)\n                 launchGlobalTimer(globalRemainingMs)\n             }\n         }\n@@ -197,7 +244,7 @@ class MainActivity : CsActivity() {\n             activeSessionId = -1\n             currentItemIndex = -1\n             adapter.setActiveItemIndex(-1)\n-            adapter.setGroupPlayingState(sessionId, false)\n+            setPlayingState(false)\n             taskNameView.text = \"Kaixo!\"\n             timerView.text = \"00:00\"\n             nextTaskView.text = \"---\"\n@@ -246,16 +293,16 @@ class MainActivity : CsActivity() {\n     }\n \n     private fun finishGroup() {\n-        isRunning = false\n-        globalTimer?.cancel()\n-        globalRemainingMs = 0\n         val doneSessionId = activeSessionId\n         activeSessionId = -1\n         currentItemIndex = -1\n+        globalTimer?.cancel()\n+        globalRemainingMs = 0\n         taskNameView.text = \"Done!\"\n         timerView.text = \"00:00\"\n         nextTaskView.text = \"---\"\n         adapter.setActiveItemIndex(-1)\n+        setPlayingState(false)\n         adapter.setGroupPlayingState(doneSessionId, false)\n     }\n \n@@ -277,8 +324,8 @@ class MainActivity : CsActivity() {\n \n     // Replace launchTimer entirely\n     private fun launchTimer(durationMs: Long) {\n-        isRunning = true\n         beepArmed = false\n+        lastBeepSecond = -1\n         updateTimerDisplay(durationMs)\n \n         currentTimer = object : CountDownTimer(durationMs, 100) {\n"
      },
      "app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt b/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt\nindex 7a7ce7b..e20048e 100644\n--- a/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt\n+++ b/app/src/main/java/com/rama/txori/adapters/SessionAdapter.kt\n@@ -53,13 +53,36 @@ class SessionAdapter(\n \n         val listView = (context as? android.app.Activity)\n             ?.findViewById<ListView>(R.id.task_list) ?: return\n+\n+        // Convert the raw items[] index to a visible list position,\n+        // accounting for collapsed rows above it\n+        val visiblePosition = rawIndexToVisiblePosition(index)\n+        if (visiblePosition < 0) return\n+\n         val firstVisible = listView.firstVisiblePosition\n-        val localPosition = index - firstVisible\n+        val localPosition = visiblePosition - firstVisible\n         if (localPosition < 0 || localPosition >= listView.childCount) return\n         val itemView = listView.getChildAt(localPosition) ?: return\n         applyProgress(progress, itemView)\n     }\n \n+    // Maps a raw index in items[] to its visible ListView position, or -1 if hidden.\n+    private fun rawIndexToVisiblePosition(rawIndex: Int): Int {\n+        val item = items.getOrNull(rawIndex) ?: return -1\n+        // If it's a row in a collapsed session it isn't visible at all\n+        if (item is SessionItem.Row && collapsedSessions.contains(item.sessionId)) return -1\n+        var visible = 0\n+        for (i in items.indices) {\n+            val current = items[i]\n+            val skip = current is SessionItem.Row && collapsedSessions.contains(current.sessionId)\n+            if (!skip) {\n+                if (i == rawIndex) return visible\n+                visible++\n+            }\n+        }\n+        return -1\n+    }\n+\n     // filter out rows belonging to collapsed sessions\n     override fun getCount(): Int {\n         var count = 0\n"
      },
