        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/res/layout/view_timer.xml b/app/src/main/res/layout/view_timer.xml\nindex 6e0992c..6c67590 100644\n--- a/app/src/main/res/layout/view_timer.xml\n+++ b/app/src/main/res/layout/view_timer.xml\n@@ -6,13 +6,58 @@\n     android:layout_height=\"match_parent\">\n \n     <TextView\n-        android:id=\"@+id/counter\"\n+        android:id=\"@+id/timer_button\"\n         android:layout_width=\"match_parent\"\n         android:layout_height=\"wrap_content\"\n         android:textSize=\"72sp\"\n-        android:gravity=\"center\"\n         android:layout_weight=\"1\"\n-        android:text=\"0\" />\n+        android:maxLength=\"8\"\n+        android:background=\"@color/bg_primary\"\n+        android:gravity=\"center\"\n+        android:text=\"\"\n+        android:hint=\"00:00:00\" />\n+\n+    <LinearLayout\n+        android:id=\"@+id/edit_view\"\n+        android:visibility=\"gone\"\n+        android:orientation=\"horizontal\"\n+        android:gravity=\"center\"\n+        android:layout_width=\"match_parent\"\n+        android:layout_height=\"0dp\"\n+        android:layout_weight=\"1\">\n+\n+        <EditText\n+            android:id=\"@+id/timer\"\n+            android:layout_width=\"wrap_content\"\n+            android:layout_height=\"wrap_content\"\n+            android:layout_weight=\"1\"\n+            android:inputType=\"number\"\n+            android:digits=\"0123456789\"\n+            android:textSize=\"72sp\"\n+            android:maxLength=\"8\"\n+            android:background=\"@color/input\"\n+            android:gravity=\"center\"\n+            android:text=\"\"\n+            android:layout_marginEnd=\"8sp\"\n+            android:hint=\"HHMMSS\"\n+            android:cursorVisible=\"false\"\n+            android:textIsSelectable=\"false\" />\n+\n+        <FrameLayout\n+            android:id=\"@+id/add_timer\"\n+            android:layout_width=\"wrap_content\"\n+            android:layout_height=\"wrap_content\"\n+            android:background=\"@color/bg_4\"\n+            android:padding=\"21sp\">\n+\n+            <ImageView\n+                android:layout_width=\"32sp\"\n+                android:layout_height=\"32sp\"\n+                android:layout_gravity=\"center\"\n+                android:src=\"@drawable/icon_plus_solid\"\n+                android:textSize=\"24sp\" />\n+        </FrameLayout>\n+    </LinearLayout>\n \n     <LinearLayout\n         android:orientation=\"vertical\"\n@@ -20,9 +65,18 @@\n         android:layout_height=\"wrap_content\">\n \n         <com.rama.txori.widgets.WdButton\n+            android:id=\"@+id/start_timer\"\n+            android:layout_width=\"match_parent\"\n+            android:layout_height=\"wrap_content\"\n+            android:text=\"Start timer\"\n+            android:layout_marginBottom=\"8sp\"\n+            android:background=\"@color/button_secondary_color\" />\n+\n+        <com.rama.txori.widgets.WdButton\n+            android:id=\"@+id/reset_timer\"\n             android:layout_width=\"match_parent\"\n             android:layout_height=\"wrap_content\"\n-            android:text=\"Reset counter\"\n+            android:text=\"Reset timer\"\n             android:layout_marginBottom=\"8sp\"\n             android:background=\"@color/button_secondary_color\" />\n \n"
