        "patch": "diff --git a/app/src/main/java/com/rama/adiskide/activities/MainActivity.kt b/app/src/main/java/com/rama/adiskide/activities/MainActivity.kt\nindex 42ff1c0..551a0c3 100644\n--- a/app/src/main/java/com/rama/adiskide/activities/MainActivity.kt\n+++ b/app/src/main/java/com/rama/adiskide/activities/MainActivity.kt\n@@ -6,12 +6,11 @@ import android.widget.ListView\n import com.rama.adiskide.CsActivity\n import com.rama.adiskide.DatabaseHelper\n import com.rama.adiskide.R\n-import com.rama.adiskide.Task\n import com.rama.adiskide.adapters.TaskAdapter\n \n class MainActivity : CsActivity() {\n     private lateinit var listView: ListView\n-    val dbHelper = DatabaseHelper(this)\n+    private val dbHelper by lazy { DatabaseHelper(this) }\n \n     override fun onCreate(savedInstanceState: Bundle?) {\n         super.onCreate(savedInstanceState)\n@@ -20,28 +19,24 @@ class MainActivity : CsActivity() {\n         val root = findViewById<View>(R.id.root)\n         applyEdgeToEdgePadding(root)\n \n-        // --- Views ---\n-\n         listView = findViewById(R.id.task_list)\n \n         val db = dbHelper.readableDatabase\n \n-        val tasks = mutableListOf<Task>()\n-        val cursor = db.rawQuery(\"SELECT * FROM tasks\", null)\n-\n-        while (cursor.moveToNext()) {\n-\n-            val id = cursor.getLong(cursor.getColumnIndexOrThrow(\"id\"))\n-            val label = cursor.getString(cursor.getColumnIndexOrThrow(\"label\"))\n-            val duration = cursor.getInt(cursor.getColumnIndexOrThrow(\"duration\"))\n+        val workouts = dbHelper.getWorkouts(db)\n \n-            tasks.add(Task(id, label, duration, 0))\n+        val tasks = if (workouts.isNotEmpty()) {\n+            dbHelper.getAllWorkoutTasks(db)\n+        } else {\n+            dbHelper.getAllTasks(db)\n         }\n \n-        cursor.close()\n-\n         val adapter = TaskAdapter(this, tasks, db)\n         listView.adapter = adapter\n+    }\n \n+    override fun onDestroy() {\n+        dbHelper.close()\n+        super.onDestroy()\n     }\n-}\n\\ No newline at end of file\n+}\n"
