      "app/build.gradle": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/build.gradle b/app/build.gradle\nnew file mode 100644\nindex 0000000..6f3b960\n--- /dev/null\n+++ b/app/build.gradle\n@@ -0,0 +1,70 @@\n+plugins {\n+    id(\"com.android.application\")\n+    id(\"org.jetbrains.kotlin.android\")\n+}\n+\n+def currentYear = java.time.LocalDate.now().getYear()\n+\n+android {\n+    namespace = \"com.rama.adiskide\"\n+    compileSdk = 36\n+\n+    defaultConfig {\n+        applicationId = \"com.rama.adiskide\"\n+        minSdk = 21\n+        targetSdk = 36\n+        versionCode = 1\n+        versionName = currentYear + \".\" + versionCode.toString()\n+    }\n+\n+    dependenciesInfo {\n+        includeInApk = false\n+        includeInBundle = false\n+    }\n+\n+    applicationVariants.all { variant ->\n+        variant.outputs.all { output ->\n+            outputFileName = \"adiskide_${versionName}.apk\"\n+        }\n+    }\n+\n+    buildTypes {\n+        release {\n+            minifyEnabled = false\n+            vcsInfo.include = false\n+            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'\n+            signingConfig = signingConfigs.debug\n+        }\n+        debug {\n+            applicationIdSuffix = \".debug\"\n+            versionNameSuffix = \"-dev\"\n+            signingConfig = signingConfigs.debug\n+        }\n+    }\n+\n+    compileOptions {\n+        sourceCompatibility = JavaVersion.VERSION_1_8\n+        targetCompatibility = JavaVersion.VERSION_1_8\n+    }\n+\n+    kotlinOptions {\n+        jvmTarget = \"1.8\"\n+    }\n+\n+    androidResources {\n+        generateLocaleConfig = true\n+    }\n+\n+    packagingOptions {\n+        exclude 'META-INF/*.version'\n+        exclude 'META-INF/com/android/build/gradle/app-metadata.properties'\n+\n+        jniLibs {\n+            useLegacyPackaging = true\n+        }\n+    }\n+}\n+\n+dependencies {\n+    implementation(libs.androidx.core.ktx)\n+}\n\\ No newline at end of file\n"
      },
